    &self,
    haystack: &[u8],
    at: usize,
    caps: &mut Self::Captures,
    dst: &mut Vec<u8>,
    mut append: F,
) -> Result<(), Self::Error>
where
    F: FnMut(&Self::Captures, &mut Vec<u8>) -> bool,
{
    let mut last_match = at;
    self.captures_iter_at(haystack, at, caps, |caps| {
        let m = caps.get(0).unwrap();
